ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| UserName!=/\$$/
| regex("(?i)(vssadmin(\\.exe)?\\s+delete\\s+shadows|wmic\\s+shadowcopy\\s+delete|bcdedit.+recoveryenabled\\s+no|bcdedit.+bootstatuspolicy\\s+ignoreallfailures|wbadmin\\s+delete\\s+(catalog|systemstatebackup)|Set-MpPreference.+DisableRealtimeMonitoring|Add-MpPreference.+ExclusionPath|Set-MpPreference.+DisableScriptScanning)", field=CommandLine)
| case {
    CommandLine=/vssadmin|shadowcopy|wbadmin/i | Bucket := "Shadow";
    CommandLine=/bcdedit/i                     | Bucket := "Boot";
    CommandLine=/MpPreference|Exclusion/i      | Bucket := "Defender";
    *                                          | Bucket := "Other";
}
| groupBy([aid, ComputerName, UserName], function=[count(as=evts), count(field=Bucket, distinct=true, as=BucketCount), collect([CommandLine, ParentBaseFileName, Bucket])])
| BucketCount>=2
